cd /pretrain_task && cat >/tmp/fusion_diag.py <<'PY'
import pickle,numpy as np
from flaw_estimator import _prepare,_fields,_pair_reduce,_analytic,_samples
from scatter import residual_fields

def shadow_maps(pre,pts):
    _,_,s,p,a,b,d,_,_,P,y,*_=pre
    g=np.eye(len(s))[p].sum(1); g=(g-g.mean(0))/g.std(0)
    f=np.column_stack([np.log(d),d]); f=(f-f.mean(0))/f.std(0)
    B=np.column_stack([np.ones(len(d)),f,g]); P2=np.eye(len(d))-B@np.linalg.solve(B.T@B+len(d)*np.diag([0,.01,.01]+[1.8]*len(s)),B.T)
    v=b-a; A=pts[:,None]-a; u=np.clip(np.sum(A*v,axis=2)/d**2,0,1)
    r=np.linalg.norm(A-u[...,None]*v,axis=2)
    out=[]
    for Q in (P,P2):
        for w in (.017,.025,.036,.052):
            k=np.exp(-.5*(r/w)**2); kP=k@Q; out.append((kP@y)/np.sqrt(np.maximum(np.sum(kP*k,1),1e-12)))
    return np.array(out)

def norm(x):
    return (x-np.median(x))/max(np.quantile(x,.98)-np.median(x),1e-12)

def prominence(f,P):
    i=f.argmax(); return (f[i]-np.max(f[np.linalg.norm(P-P[i],axis=1)>.1]))/(np.quantile(f,.98)-np.median(f))

if __name__=='__main__':
 for c in pickle.load(open('calibration_cases.pkl','rb')):
    b=c['bundle']; g=c['ground_truth_flaw']/max(b['target_plate']); pre=_prepare(b); L,plate=pre[:2]; grid=[np.linspace(0,w,round(w/.009)+1) for w in plate]; P=np.array(np.meshgrid(*grid)).reshape(2,-1).T
    if pre[-1]: continue
    raw=shadow_maps(pre,P); sh=np.array([norm(v) for v in raw]); err=lambda f:round(np.linalg.norm(P[f.argmax()]-g),4)
    print(c['case_id'],'shadow error and peaks',[(err(v),round(v.max(),3),round(prominence(v,P),3),round(u.max(),3)) for u,v in zip(raw,sh)])
    for r in (.012,.035,.08):
        co,pars=residual_fields(b,pre,P,r); sigma,ph,coef,norms,detect,ts=pars; i=np.argmin(np.linalg.norm(P-g,axis=1)); print('ridge',r,'scatter abs stats',np.round(np.quantile(detect,[.5,.9,.99]),4),'rel',np.round(np.quantile(detect/abs(coef[:,0,None]),[.5,.9,.99]),4)); print('coda',[(err(f),round(norm(f).max(),3),round(prominence(f,P),3)) for f in co[:4]])
        for shx in (sh[1],sh[2],sh[5],sh[6],.5*(sh[2]+sh[5]),np.max(sh,axis=0)):
            print('mix',[[err(shx+w*norm(co[k])) for w in (.1,.25,.5,1,2,4)] for k in (0,2)])
